const { withAppBuildGradle } = require("expo/config-plugins");

/*
 * Signs release builds with a real keystore instead of the debug one.
 *
 * Expo's template points `buildTypes.release` at `signingConfigs.debug` and
 * warns about it in a comment. A debug-signed APK is not just informal — its
 * signature cannot be changed later, so anyone who installs one must uninstall
 * (losing their recordings) before a properly signed build will go on.
 *
 * `android/` is gitignored and regenerated by prebuild, so this cannot be a
 * hand-edit of build.gradle; it has to run as a config plugin every time.
 *
 * Credentials come from `android/keystore.properties`, which is gitignored and
 * never generated here. A release build without it fails at configuration time
 * rather than quietly falling back to debug signing.
 */

const RELEASE_SIGNING_CONFIG = `
        release {
            def keystorePropertiesFile = rootProject.file('keystore.properties')
            if (keystorePropertiesFile.exists()) {
                def keystoreProperties = new Properties()
                keystorePropertiesFile.withInputStream { keystoreProperties.load(it) }
                storeFile file(keystoreProperties.getProperty('storeFile'))
                storePassword keystoreProperties.getProperty('storePassword')
                keyAlias keystoreProperties.getProperty('keyAlias')
                keyPassword keystoreProperties.getProperty('keyPassword')
            } else if (gradle.startParameter.taskNames.any { it.toLowerCase().contains('release') }) {
                throw new GradleException(
                    "Release signing needs android/keystore.properties, which is missing.\\n" +
                    "See docs/releasing.md. Refusing to sign a release build with the debug key."
                )
            }
        }`;

/** The template block this plugin replaces. Matched exactly so an SDK bump that
 * rewrites it fails loudly rather than leaving release builds debug-signed. */
const DEBUG_SIGNED_RELEASE = `        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug`;

const RELEASE_SIGNED_RELEASE = `        release {
            // Signed from android/keystore.properties by plugins/with-release-signing.js.
            signingConfig signingConfigs.release`;

const DEBUG_SIGNING_CONFIG = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }`;

function anchor(contents, needle, what) {
  if (!contents.includes(needle)) {
    throw new Error(
      `with-release-signing: could not find ${what} in android/app/build.gradle. ` +
        `The Expo template has changed; update the plugin before releasing, because ` +
        `the fallback is a debug-signed release build.`,
    );
  }
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (gradleConfig) => {
    let contents = gradleConfig.modResults.contents;

    anchor(contents, DEBUG_SIGNING_CONFIG, "the debug signingConfig");
    anchor(contents, DEBUG_SIGNED_RELEASE, "the debug-signed release buildType");

    contents = contents.replace(
      DEBUG_SIGNING_CONFIG,
      DEBUG_SIGNING_CONFIG + RELEASE_SIGNING_CONFIG,
    );
    contents = contents.replace(DEBUG_SIGNED_RELEASE, RELEASE_SIGNED_RELEASE);

    gradleConfig.modResults.contents = contents;
    return gradleConfig;
  });
};
